/* x: all LYRA_SEIZEIT2_N_FEATURES features, every one available (else the window is suppressed). */
static inline float lyra_seizeit2_score(const float x[LYRA_SEIZEIT2_N_FEATURES]) {
    double sum = 0.0;
    for (int t = 0; t < LYRA_SEIZEIT2_N_TREES; t++) {
        const int32_t base = lyra_seizeit2_root[t];
        int32_t n = 0;
        while (lyra_seizeit2_feature[base + n] >= 0) {
            const float v = x[lyra_seizeit2_column[lyra_seizeit2_feature[base + n]]];
            n = (v <= lyra_seizeit2_threshold[base + n]) ? lyra_seizeit2_left[base + n]
                                                          : lyra_seizeit2_right[base + n];
        }
        sum += lyra_seizeit2_value[base + n];
    }
    return (float)(sum / LYRA_SEIZEIT2_N_TREES);
}

